text.faceKit606:
function faceKit606(g,A,B){
  const k=(B[1]-A[1])/((B[0]-A[0])||1),lo=Math.min(A[0],B[0]),hi=Math.max(A[0],B[0]);
  const row=x=>Math.ceil(A[1]+(x+.5-A[0])*k-.5)-1;
  const xAt=t=>Math.floor(A[0]+(B[0]-A[0])*t);
  const cols=(t0,t1)=>{let a=xAt(t0),b=xAt(t1);if(a>b){const q=a;a=b;b=q;}a=Math.max(a,Math.ceil(lo));b=Math.min(b,Math.floor(hi)-1);const o=[];for(let x=a;x<=b;x++)o.push(x);return o;};
  const band=(t0,t1,e0,e1,col)=>{g.fillStyle=col;for(const x of cols(t0,t1))g.fillRect(x,row(x)-e1+1,1,e1-e0);};
  const px=(x,e,col,w=1,h=1)=>{g.fillStyle=col;g.fillRect(x,row(x)-e-h+1,w,h);};
  return {k,row,xAt,cols,band,px,len:Math.abs(B[0]-A[0])};
}

