function paintNear606(g,w,s,cat,hb,lv){ // T599 的原意（花台、垃圾桶、冷氣機、工安標線、棧板、管線）落在真的牆腳與側牆
  const t=s.__t547,seed=(t.v|0)*131+(t.bw|0)*17+(t.bh|0)*7+hb*1013;let n=0;
  const L=faceKit606(g,w.W,w.S),D=faceKit606(g,w.S,w.E);
  if(cat==='R'||cat==='C'){
    const nb=Math.max(1,Math.round(L.len/11));
    for(let i=0;i<nb;i++){const hh=streetHash(seed,i,60620);if(hh<.30)continue;
      const x=L.xAt((i+.3+.4*streetHash(seed,i,60621))/nb);
      if(hh<.62){ // 花台：陶盆一列＋兩色葉＋偶爾一朵花
        L.px(x,0,'#6a4a32',3,1);L.px(x,1,'#3f7f43',3,1);L.px(x+1,2,'#5b9e55',1,1);if(hh>.5)L.px(x+2,2,'#c45a6a',1,1);
      }else if(cat==='R'){ // 帶蓋垃圾桶
        L.px(x,0,'#2f4a3a',2,2);L.px(x,2,'#3f6450',2,1);
      }else{ // 立牌
        L.px(x,0,'#2b2f36',2,3);L.px(x,1,'#e8dcb0',1,1);
      }
      n++;}
    if(w.h>=12&&D.len>=8){const nu=cat==='C'?2:1;
      for(let i=0;i<nu;i++){const hh=streetHash(seed,i,60625);if(hh<.25)continue;
        const x=D.xAt(.25+.5*(i+hh*.5)/nu),e=Math.min(w.h-5,Math.round(w.h*(.35+.3*hh)));
        D.px(x,e,'#b7bec3',3,2);D.px(x,e,'#6c767d',3,1);D.px(x+1,e+1,'#8d979d',1,1);D.px(x,e-1,'rgba(30,34,38,.22)',3,1);n++;}}
  }else{ // 工業：牆腳工安斜紋、棧板、側牆立管
    const cs=L.cols(.06,.94);
    for(const x of cs){const r=L.row(x);for(let e=0;e<2;e++){const on=((x+e)>>1)&1;g.fillStyle=on?'#d7a93e':'#2a2e31';g.fillRect(x,r-e,1,1);}}n++;
    const np=Math.max(1,Math.round(L.len/18));
    for(let i=0;i<np;i++){const hh=streetHash(seed,i,60640);if(hh<.35)continue;const x=L.xAt((i+.35)/np)+1;L.px(x,2,'#9a7a4e',4,1);L.px(x,3,'#b4925e',4,1);if(hh>.7)L.px(x+1,4,'#6f8a9c',2,2);n++;}
    if(w.h>=10&&D.len>=6){const x=D.xAt(.3+.4*streetHash(seed,1,60641));g.fillStyle='#5e6b6a';g.fillRect(x,D.row(x)-w.h+2,1,w.h-2);g.fillStyle='#8a9695';g.fillRect(x,D.row(x)-w.h+2,1,1);n++;}
  }
  return n;
}

text.paintWeather606:
function paintWeather606(g,w,s,cat,mood,tt){ // T591 的原意（雨漬、接地苔垢、簷下積灰）落在真的牆上
  const t=s.__t547,seed=(t.v|0)*131+(t.bw|0)*17+(t.bh|0)*7+(t.lv|0)*3;let n=0;
  const wc=(WX606[cat]||WX606.R)[mood&3];
  const moss=cat==='R'&&mood===2,grime=moss?'rgba(74,110,64,':'rgba(58,54,48,';
  const faces=[[w.W,w.S,1,0],[w.S,w.E,.8,1]];
  for(const [A,B,am,fi] of faces){
    const F=faceKit606(g,A,B);if(F.len<4||w.h<6)continue;
    const ns=Math.max(1,Math.round(F.len/(fi?11:8)));
    for(let i=0;i<ns;i++){
      const hh=streetHash(seed,i+fi*40,60610);if(hh>.46+tt*.36)continue;
      const tx=(i+.25+.5*streetHash(seed,i+fi*40,60611))/ns,x=F.xAt(tx);
      const L=Math.max(2,Math.min(w.h-3,Math.round(w.h*(.20+.38*hh)*(.6+tt*.7))));
      const a=(.10+tt*.16)*(.7+.3*hh)*am,top=w.h-2;
      const up=Math.max(1,Math.round(L*.45));
      g.fillStyle=wc+(a*.55).toFixed(3)+')';g.fillRect(x,F.row(x)-top,1,up);
      g.fillStyle=wc+a.toFixed(3)+')';g.fillRect(x,F.row(x)-top+up,1,L-up);
      if(tt>.5&&hh<.2){g.fillStyle=wc+(a*.5).toFixed(3)+')';g.fillRect(x+1,F.row(x+1)-top+up,1,Math.max(1,L-up-2));}
      n++;
    }
    F.band(0,1,0,tt>.55?2:1,grime+((.10+tt*.15)*am).toFixed(3)+')');n++;
    if(tt>.25){F.band(0,1,w.h-2,w.h-1,'rgba(40,38,36,'+((.05+tt*.07)*am).toFixed(3)+')');}
  }
  return n;
}

