function drawWallDetail606(ctx,o,bd,s,bx,by,z){
  const t5=s&&s.__t547;if(window.__noWallDetail606||!t5||!t5.wall||!bd||bd.ref||bd.k===4)return 0;
  if(String(t5.sty||'').indexOf('f577:')===0)return 0; // 英美立面在精靈內自帶門窗花台，不再疊
  const age=bd.age|0,cat=bd.k===1?'R':bd.k===2?'C':'I',a0=ctx.globalAlpha,dA=detailAlpha432(z);if(dA<=0)return 0;
  let n=0;const put=e=>{if(!e)return;ctx.globalAlpha=a0*dA;ctx.drawImage(e.c,bx+e.x*z,by+e.y*z,e.c.width*z,e.c.height*z);n++;};
  if(age>=14&&z>=.9&&!window.__noAgeW591){
    const ab=age<120?1:age<240?2:3,mood=districtMood424(o.x,o.y);
    put(wallCache606(s,'w'+ab+mood+cat,(g,w,sp)=>paintWeather606(g,w,sp,cat,mood,[0,.3,.6,.95][ab])));
  }
  if(z>=1.22&&age>=9&&!window.__noNearZoom599&&streetHash(o.x,o.y,60630)<.72){
    const hb=Math.floor(streetHash(o.x,o.y,60631)*3);
    put(wallCache606(s,'n'+hb+cat+(bd.lv||1),(g,w,sp)=>paintNear606(g,w,sp,cat,hb,bd.lv||1)));
  }
  ctx.globalAlpha=a0;if(n)window.__t606Wall=(window.__t606Wall||0)+1;return n;
}

